# 修复飞书中文文件名乱码

## 问题原因
`form-data` 库把中文文件名直接放入 HTTP 头的双引号中，导致编码问题。

## 修复方法：使用临时文件（推荐）

### 步骤 1：编辑文件
```bash
sudo nano /usr/lib/node_modules/openclaw/extensions/feishu/src/media.ts
```

### 步骤 2：添加临时文件导入
在文件顶部添加：
```typescript
import { tmpdir } from "os";
import { join, extname } from "path";
import { copyFile, unlink, writeFile } from "fs/promises";
import { randomBytes } from "crypto";
```

### 步骤 3：修改 `sanitizeFileNameForUpload` 函数
找到这个函数（约第 227 行），替换为：
```typescript
/**
 * 修复中文文件名乱码问题
 * 策略：保留原始文件名，实际修复在 uploadFileFeishu 中通过临时文件实现
 */
export function sanitizeFileNameForUpload(fileName: string): string {
  // 不再进行 encodeURIComponent，直接返回原始文件名
  return fileName;
}
```

### 步骤 4：添加临时文件辅助函数
在 `sanitizeFileNameForUpload` 函数后添加：
```typescript
/**
 * 创建临时英文文件名
 */
function createTempFilePath(originalFileName: string): string {
  const ext = extname(originalFileName) || '.bin';
  const randomSuffix = randomBytes(8).toString('hex');
  const tempName = `feishu_${randomSuffix}${ext}`;
  return join(tmpdir(), tempName);
}
```

### 步骤 5：修改 `uploadFileFeishu` 函数
找到 `uploadFileFeishu` 函数（约第 250 行），替换整个函数为：
```typescript
/**
 * Upload a file to Feishu and get a file_key for sending.
 * Max file size: 30MB
 * 
 * 修复：使用临时文件解决中文文件名乱码问题
 */
export async function uploadFileFeishu(params: {
  cfg: ClawdbotConfig;
  file: Buffer | string;
  fileName: string;
  fileType: "opus" | "mp4" | "pdf" | "doc" | "xls" | "ppt" | "stream";
  duration?: number;
  accountId?: string;
}): Promise<UploadFileResult> {
  const { cfg, file, fileName, fileType, duration, accountId } = params;

  // 检查是否需要临时文件修复
  const ASCII_ONLY = /^[\x00-\x7F]+$/;
  const needsTempFile = !ASCII_ONLY.test(fileName);

  if (needsTempFile) {
    // 中文文件名，使用临时文件修复
    const tempPath = createTempFilePath(fileName);

    try {
      // 复制文件到临时位置（使用英文文件名）
      if (typeof file === "string") {
        await copyFile(file, tempPath);
      } else {
        await writeFile(tempPath, file);
      }

      // 使用临时文件上传，但保留原始中文文件名作为显示名
      return await uploadFileFeishuInternal({
        cfg,
        file: tempPath,
        fileName,  // 原始中文文件名，用户会看到这个
        fileType,
        duration,
        accountId
      });
    } finally {
      // 清理临时文件
      await unlink(tempPath).catch(() => {});
    }
  }

  // ASCII 文件名，直接上传
  return uploadFileFeishuInternal({ cfg, file, fileName, fileType, duration, accountId });
}

/**
 * 内部实现：实际执行文件上传
 */
async function uploadFileFeishuInternal(params: {
  cfg: ClawdbotConfig;
  file: Buffer | string;
  fileName: string;
  fileType: "opus" | "mp4" | "pdf" | "doc" | "xls" | "ppt" | "stream";
  duration?: number;
  accountId?: string;
}): Promise<UploadFileResult> {
  const { cfg, file, fileName, fileType, duration, accountId } = params;

  const account = resolveFeishuAccount({ cfg, accountId });
  if (!account.configured) {
    throw new Error(`Feishu account "${account.accountId}" not configured`);
  }

  const client = createFeishuClient({
    ...account,
    httpTimeoutMs: FEISHU_MEDIA_HTTP_TIMEOUT_MS,
  });

  const fileData = typeof file === "string" ? fs.createReadStream(file) : file;

  // 不再对文件名进行编码，直接传递原始文件名
  const safeFileName = fileName;

  const response = await client.im.file.create({
    data: {
      file_type: fileType,
      file_name: safeFileName,
      file: fileData as any,
      ...(duration !== undefined && { duration }),
    },
  });

  const responseAny = response as any;
  if (responseAny.code !== undefined && responseAny.code !== 0) {
    throw new Error(`Feishu file upload failed: ${responseAny.msg || `code ${responseAny.code}`}`);
  }

  const fileKey = responseAny.file_key ?? responseAny.data?.file_key;
  if (!fileKey) {
    throw new Error("Feishu file upload failed: no file_key returned");
  }

  return { fileKey };
}
```

